// Step 1: Create AcroForm PDF
var doc = new Aspose.Pdf.Document();
var page = doc.Pages.Add();
var nameField = new Aspose.Pdf.Forms.TextBoxField(page, new Aspose.Pdf.Rectangle(50, 700, 200, 750));
nameField.PartialName = "Name";
nameField.Value = "John Doe";
doc.Form.Add(nameField, 1);
doc.Save("acroform.pdf");

// Step 2: Test FormFlattener
var opt = new Aspose.Pdf.LowCode.FormFlattenAllFieldsOptions();
opt.AddInput(new Aspose.Pdf.LowCode.FileDataSource("acroform.pdf"));
opt.AddOutput(new Aspose.Pdf.LowCode.FileDataSource("flattened.pdf"));
new Aspose.Pdf.LowCode.FormFlattener().Process(opt);
Console.WriteLine(File.Exists("flattened.pdf") ? "PASS" : "FAIL");
